/* ================================ TOUCH ================================= */
#touchControls { position: absolute; inset: 0; z-index: 13; pointer-events: none; }
#touchControls .stick {
  position: absolute;
  width: 132px; height: 132px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(10, 15, 30, 0.18) 40%, rgba(10, 15, 30, 0.42));
  border: 1px solid rgba(255, 255, 255, 0.14);
  pointer-events: auto;
  touch-action: none;
  backdrop-filter: blur(3px);
}
#touchControls .stick.aim { border-color: color-mix(in srgb, var(--pick) 45%, transparent); }
#moveStick { left: calc(18px + var(--safe-left)); bottom: calc(18px + var(--safe-bottom)); }
#aimStick { right: calc(18px + var(--safe-right)); bottom: calc(18px + var(--safe-bottom)); }
.stick-ring { position: absolute; inset: 22px; border: 1px dashed rgba(255, 255, 255, 0.16); border-radius: 50%; }
.stick-knob {
  position: absolute; left: 50%; top: 50%;
  width: 56px; height: 56px; border-radius: 50%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.28), rgba(18, 24, 42, 0.85));
  border: 1px solid rgba(255, 255, 255, 0.3);
  box-shadow: 0 6px 20px -6px #000;
}
#aimStick .stick-knob { border-color: color-mix(in srgb, var(--pick) 60%, transparent); box-shadow: 0 0 18px -6px var(--pick); }
.stick-label {
  position: absolute; bottom: 8px; left: 0; right: 0;
  text-align: center; font-size: 7px; font-weight: 700; letter-spacing: 0.2em; color: #96a1bc;
}
.touch-btn {
  position: absolute;
  width: 60px; height: 60px;
  border-radius: 50%;
  display: grid; place-items: center;
  background: rgba(9, 13, 27, 0.7);
  border: 1px solid var(--line);
  color: #dbe3f7;
  pointer-events: auto;
  touch-action: none;
  backdrop-filter: blur(8px);
  transition: transform 0.1s, opacity 0.2s;
}
.touch-btn .icon { width: 25px; height: 25px; }
.touch-btn:active { transform: scale(0.9); }
.touch-btn i { position: absolute; inset: -2px; border-radius: 50%; background: conic-gradient(rgba(3, 5, 12, 0.72) calc(var(--cd, 0) * 1turn), transparent 0); }
.touch-btn.ult { --c: var(--pick); border-color: color-mix(in srgb, var(--c) 55%, transparent); color: var(--c); }
.touch-btn.ult.ready { box-shadow: 0 0 26px -4px var(--c); }
#touchDash { right: calc(166px + var(--safe-right)); bottom: calc(34px + var(--safe-bottom)); }
#touchUlt { right: calc(38px + var(--safe-right)); bottom: calc(166px + var(--safe-bottom)); }

/* ================================ MODALS ================================ */
.modal {
  position: absolute; inset: 0; z-index: 40;
  display: grid; place-items: center;
  padding: 20px;
  background: rgba(2, 4, 10, 0.7);
  backdrop-filter: blur(10px);
}
.modal-panel {
  position: relative;
  width: min(860px, 100%);
  max-height: min(86vh, 760px);
  overflow-y: auto;
  padding: 30px 38px 26px;
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.05), transparent 32%),
    linear-gradient(180deg, rgba(12, 16, 32, 0.97), rgba(6, 9, 20, 0.97));
  border: 1px solid var(--line);
  border-top-color: rgba(232, 200, 138, 0.4);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
