  text-transform: uppercase;
}
.how-block p { margin: 0 0 14px; font-size: 13.5px; line-height: 1.55; color: #aeb9d3; font-weight: 500; }
.how-objective { display: flex; gap: 11px; align-items: center; padding: 11px 13px; background: rgba(255, 255, 255, 0.03); border-left: 2px solid var(--gold-deep); font-size: 11.5px; line-height: 1.4; color: #95a1be; }
.how-objective .icon { flex: 0 0 auto; width: 28px; height: 28px; color: var(--gold); }
