+
+  updatePlayer(dt) {
+    const f = this.player;
+    const el = f.el;
+    const input = this.input;
+    const pos = f.avatar.root.position;
+
+    let mx = input.moveX || 0;
+    let mz = -(input.moveZ || 0);
+    const mlen = Math.hypot(mx, mz);
+    if (mlen > 1) { mx /= mlen; mz /= mlen; }
+    const speed = el.moveSpeed * (f.slowTime > 0 ? 0.62 : 1);
