+  }
+
+  tryDash() {
+    const f = this.player;
+    if (!f || this.state !== 'playing' || !f.alive || f.dashCd > 0 || f.stunTime > 0) return;
+    let dx = this.input.moveX || 0;
+    let dz = -(this.input.moveZ || 0);
