+      }
+    }
+
+    const dx = tx - p.x;
+    const dz = tz - p.z;
+    const dist = Math.hypot(dx, dz) || 1;
+    let ix = 0;
+    let iz = 0;
+    if (f.ai.mode === 'retreat') {
+      if (dist > 3) { ix = dx / dist; iz = dz / dist; }
+    } else if (dist > desiredRange + 1.3) {
+      ix = dx / dist;
+      iz = dz / dist;
+    } else if (dist < desiredRange - 3.2) {
+      ix = -dx / dist;
+      iz = -dz / dist;
+    } else {
+      f.ai.strafeT -= dt;
+      if (f.ai.strafeT <= 0) {
