+        f.ai.strafe *= -1;
+      }
+      ix = (-dz / dist) * f.ai.strafe * 0.7;
+      iz = (dx / dist) * f.ai.strafe * 0.7;
+    }
+
+    /* arena edge and own tower avoidance */
+    const rad = Math.hypot(p.x, p.z);
