+      if (f.attackCd <= 0 && f.stunTime <= 0 && td < (target.type === 'tower' ? 32 : 27)) {
+        this.spawnBasic(f, this.tmpVec2.set(jx, 0, jz).clone());
+        f.attackCd = el.attackCd * (0.92 + Math.random() * 0.22);
+      }
+
+      if (f.ult >= 100 && f.stunTime <= 0 && td < 30 && Math.random() < 0.5) {
+        f.ult = 0;
