              this.damageTower(o, 11, owner, {});
            }
          }
        }
      }
    }
  }

  schedule(delay, fn) {
    this.scheduled.push({ t: delay, fn });
  }

  updateScheduled(dt) {
    for (let i = this.scheduled.length - 1; i >= 0; i--) {
      const s = this.scheduled[i];
      s.t -= dt;
      if (s.t <= 0) {
        this.scheduled.splice(i, 1);
        try { s.fn(); } catch (err) { console.error(err); }
      }
    }
