488:     } else if (dist > desiredRange + 1.3) {
489:       ix = dx / dist;
490:       iz = dz / dist;
491:     } else if (dist < desiredRange - 3.2) {
492:       ix = -dx / dist;
493:       iz = -dz / dist;
494:     } else {
495:       f.ai.strafeT -= dt;
496:       if (f.ai.strafeT <= 0) {
497:         f.ai.strafeT = 1.2 + Math.random() * 1.4;
498:         f.ai.strafe *= -1;
499:       }
500:       ix = (-dz / dist) * f.ai.strafe * 0.7;
501:       iz = (dx / dist) * f.ai.strafe * 0.7;
502:     }
503: 
504:     /* arena edge and own tower avoidance */
505:     const rad = Math.hypot(p.x, p.z);
506:     if (rad > PLAY_RADIUS - 3) {
507:       ix += (-p.x / rad) * 1.8;
508:       iz += (-p.z / rad) * 1.8;
509:     }
510: 
511:     /* retreat from melee pressure */
512:     if (f.ai.mode === 'retreat' && target && target.type === 'avatar') {
513:       const nd = Math.hypot(target.faction.avatar.root.position.x - p.x, target.faction.avatar.root.position.z - p.z);
514:       if (nd < 9) {
515:         ix += (p.x - target.faction.avatar.root.position.x) / (nd || 1) * 0.8;
516:         iz += (p.z - target.faction.avatar.root.position.z) / (nd || 1) * 0.8;
517:       }
518:     }
519: 
520:     const ilen = Math.hypot(ix, iz);
521:     if (ilen > 1e-4) {
522:       ix /= ilen;
523:       iz /= ilen;
524:       const speed = el.moveSpeed * (f.slowTime > 0 ? 0.62 : 1);
525:       p.x += ix * speed * dt;
526:       p.z += iz * speed * dt;
527:       this.constrainAvatar(f);
528:     }
529: 
530:     /* aim & attack */
531:     if (target) {
532:       const tp = target.type === 'avatar'
533:         ? target.faction.avatar.root.position
534:         : target.faction.tower.group.position;
535:       const td = Math.hypot(tp.x - p.x, tp.z - p.z);
536:       const targetRot = Math.atan2(tp.x - p.x, tp.z - p.z);
537:       f.avatar.root.rotation.y = angleLerp(f.avatar.root.rotation.y, targetRot, dt * 7);
538: 
539:       let aimX = tp.x;
540:       let aimZ = tp.z;
541:       if (target.type === 'avatar') {
542:         const lead = Math.min(0.65, td / (el.projectileSpeed * 2.4));
543:         aimX += target.faction.vel.x * lead * 8;
544:         aimZ += target.faction.vel.z * lead * 8;
545:       }
546:       const aimDist = Math.hypot(aimX - p.x, aimZ - p.z) || 1;
547:       let dirX = (aimX - p.x) / aimDist;
548:       let dirZ = (aimZ - p.z) / aimDist;
549:       const jitter = (Math.random() - 0.5) * (target.type === 'tower' ? 0.045 : 0.11);
550:       const cs = Math.cos(jitter);
551:       const sn = Math.sin(jitter);
552:       const jx = dirX * cs - dirZ * sn;
553:       const jz = dirX * sn + dirZ * cs;
554: 
555:       if (f.attackCd <= 0 && f.stunTime <= 0 && td < (target.type === 'tower' ? 32 : 27)) {
556:         this.spawnBasic(f, this.tmpVec2.set(jx, 0, jz).clone());
557:         f.attackCd = el.attackCd * (0.92 + Math.random() * 0.22);
558:       }
559: 
560:       if (f.ult >= 100 && f.stunTime <= 0 && td < 30 && Math.random() < 0.5) {
561:         f.ult = 0;
562:         const at = new THREE.Vector3(aimX, 0, aimZ);
563:         if (f.id === 'water') at.set(p.x, 0, p.z);
564:         this.castUlt(f, at);
565:       }
566:     }
567: 
568:     /* desperate dodge */
569:     if (f.hp / f.maxHp < 0.38 && f.dashCd <= 0 && Math.random() < 0.35) {
570:       let nearest = null;
571:       let nd = 9;
572:       for (const o of this.factions) {
573:         if (o === f || !o.alive) continue;
574:         const d = Math.hypot(o.avatar.root.position.x - p.x, o.avatar.root.position.z - p.z);
575:         if (d < nd) { nd = d; nearest = o; }
576:       }
577:       if (nearest) {
578:         const ax = p.x - nearest.avatar.root.position.x;
579:         const az = p.z - nearest.avatar.root.position.z;
580:         const al = Math.hypot(ax, az) || 1;
581:         f.dashDir.set(ax / al, 0, az / al);
582:         f.dashTime = 0.18;
583:         f.dashCd = 5;
584:         f.invuln = Math.max(f.invuln, 0.3);
585:         this.fx.burst(p.x, 1.2, p.z, el.color, 16, { speed: 5, size: 0.6, life: 0.5 });
586:       }
587:     }
588: 
589:     if (f.dashTime > 0) {
590:       p.x += f.dashDir.x * 47 * dt;
591:       p.z += f.dashDir.z * 47 * dt;
592:       this.constrainAvatar(f);
593:     }
594:   }
595: 
596:   chooseAITarget(f) {
597:     const p = f.avatar.root.position;
598:     const enemies = this.factions.filter((o) => o !== f && o.towerAlive);
599:     const armed = enemies.filter((o) => o.alive);
600:     const hpFrac = f.hp / f.maxHp;
601: 
602:     if (hpFrac < 0.3 && f.towerAlive) {
603:       f.ai.mode = 'retreat';
604:       f.ai.target = { type: 'home' };
605:       return;
606:     }
607:     if (f.ai.mode === 'retreat' && hpFrac < 0.66) {
608:       f.ai.target = { type: 'home' };
609:       return;
610:     }
611:     f.ai.mode = 'fight';
612: 
613:     let nearest = null;
614:     let nearestD = Infinity;
615:     for (const o of armed) {
616:       const d = Math.hypot(o.avatar.root.position.x - p.x, o.avatar.root.position.z - p.z);
617:       if (d < nearestD) { nearestD = d; nearest = o; }
618:     }
619: 
620:     /* defend the home nexus */
621:     let defender = null;
622:     for (const o of armed) {
623:       const dt = Math.hypot(o.avatar.root.position.x - f.home.x, o.avatar.root.position.z - f.home.z);
624:       if (dt < 11 && Math.hypot(o.avatar.root.position.x - p.x, o.avatar.root.position.z - p.z) < 24) {
625:         defender = o;
626:         break;
627:       }
628:     }
629: 
630:     if (defender) {
631:       f.ai.target = { type: 'avatar', faction: defender };
632:       return;
633:     }
634:     if (nearest && nearestD < 17 && Math.random() < 0.62) {
635:       f.ai.target = { type: 'avatar', faction: nearest };
636:       return;
637:     }
638: 
639:     const towers = enemies.filter((o) => o.towerAlive);
640:     if (!towers.length) {
641:       if (nearest) f.ai.target = { type: 'avatar', faction: nearest };
642:       else f.ai.target = { type: 'home' };
643:       return;
644:     }
645:     /* the player's nexus is the prize; weigh it heavier */
646:     let pick = null;
647:     let bestScore = -Infinity;
648:     for (const o of towers) {
649:       let score = Math.random() * 30;
650:       score += (1 - o.towerHp / o.towerMax) * 35;
651:       if (o.isPlayer) score += 24;
652:       if (o === nearest) score += 8;
653:       if (score > bestScore) { bestScore = score; pick = o; }
654:     }
655:     f.ai.target = { type: 'tower', faction: pick };
656:   }
657: 
658:   /* ------------------------------ collisions ------------------------------ */
659: 
660:   constrainAvatar(f) {
661:     const p = f.avatar.root.position;
662:     const rad = Math.hypot(p.x, p.z);
663:     const maxR = PLAY_RADIUS - 0.6;
664:     if (rad > maxR) {
665:       p.x = (p.x / rad) * maxR;
666:       p.z = (p.z / rad) * maxR;
667:     }
668:     for (const o of this.factions) {
669:       if (!o.towerAlive) continue;
670:       const tp = o.tower.group.position;
671:       const dx = p.x - tp.x;
672:       const dz = p.z - tp.z;
673:       const d = Math.hypot(dx, dz);
674:       const min = TOWER_RADIUS + AVATAR_RADIUS - 0.2;
675:       if (d < min && d > 0.001) {
676:         p.x = tp.x + (dx / d) * min;
677:         p.z = tp.z + (dz / d) * min;
678:       }
679:     }
680:   }
681: 
682:   resolveCollisions() {
683:     for (let i = 0; i < this.factions.length; i++) {
684:       const a = this.factions[i];
685:       if (!a.alive) continue;
686:       for (let j = i + 1; j < this.factions.length; j++) {
687:         const b = this.factions[j];
688:         if (!b.alive) continue;
689:         const pa = a.avatar.root.position;
690:         const pb = b.avatar.root.position;
691:         const dx = pb.x - pa.x;
692:         const dz = pb.z - pa.z;
693:         const d = Math.hypot(dx, dz);
694:         const min = AVATAR_RADIUS * 2 + 0.15;
695:         if (d < min && d > 0.001) {
696:           const push = (min - d) * 0.5;
697:           pa.x -= (dx / d) * push;
698:           pa.z -= (dz / d) * push;
699:           pb.x += (dx / d) * push;
700:           pb.z += (dz / d) * push;
701:           this.constrainAvatar(a);
702:           this.constrainAvatar(b);
703:         }
704:       }
705:     }
706:   }
707: 
708:   updateVelocities(dt) {
709:     for (const f of this.factions) {
710:       const p = f.avatar.root.position;
711:       f.vel.set((p.x - f.lastPos.x) / Math.max(dt, 0.0001), 0, (p.z - f.lastPos.z) / Math.max(dt, 0.0001));
712:       f.moved = Math.hypot(p.x - f.lastPos.x, p.z - f.lastPos.z);
713:       f.lastPos.copy(p);
714:     }
715:   }
716:   /* -------------------------------- towers -------------------------------- */
717: 
718:   updateTower(f, dt) {
719:     f.tower.update(this.time + f.el.angle, dt);
720: 
721:     if (f.towerAlive) {
722:       f.towerCd -= dt;
723:       if (f.towerCd <= 0) {
724:         const tp = f.tower.group.position;
725:         let target = null;
726:         let best = 21.5 * 21.5;
727:         for (const o of this.factions) {
728:           if (o === f || !o.alive || !o.towerAlive) continue;
729:           const p = o.avatar.root.position;
730:           const d = (p.x - tp.x) ** 2 + (p.z - tp.z) ** 2;
731:           if (d < best) { best = d; target = o; }
732:         }
733:         if (target) {
734:           this.spawnTowerBolt(f, target);
735:           f.towerCd = 1.35 + Math.random() * 0.35;
736:         } else {
737:           f.towerCd = 0.35;
738:         }
739:       }
740:     } else if (f.towerDeath !== null) {
741:       f.towerDeath += dt;
742:       const k = Math.min(1, f.towerDeath / 2.5);
743:       f.tower.group.position.y = -k * 13;
744:       f.tower.group.rotation.z = k * 0.26;
745:       f.tower.group.rotation.x = k * 0.09;
746:       f.tower.beamMat.opacity = (1 - k) * 0.18;
747:       f.tower.beamWide.material.opacity = (1 - k) * 0.04;
748:       f.tower.topGlow.material.opacity = (1 - k) * 0.3;
749:       f.tower.coreGlow.material.opacity = (1 - k) * 0.5;
750:       f.tower.light.intensity = (1 - k) * 10;
751:       if (k >= 1) {
752:         f.tower.group.visible = false;
753:         f.towerDeath = null;
754:       }
755:     }
756:   }
757: 
758:   spawnTowerBolt(f, target) {
759:     const tp = f.tower.group.position;
760:     const from = new THREE.Vector3(tp.x, 8.6, tp.z);
761:     const to = target.avatar.root.position;
762:     const dir = new THREE.Vector3(to.x - from.x, 2.0 - from.y, to.z - from.z).normalize();
763:     const p = this.spawnProjectile({
764:       element: f.id,
765:       owner: f,
766:       from,
767:       vel: dir.multiplyScalar(29),
768:       damage: 21,
769:       towerDamage: 0,
770:       splash: 0,
771:       canHitTower: false,
772:       isTower: true,
773:       life: 1.5
774:     });
775:     this.fx.flash(from.x, from.y, from.z, f.el.color, 2.4, 0.16);
776:     return p;
777:   }
778: 
779:   /* ------------------------------ projectiles ----------------------------- */
780: 
781:   spawnBasic(f, dir) {
782:     const el = f.el;
783:     const speed = el.projectileSpeed;
784:     const origin = f.avatar.root.position.clone();
785:     origin.y += 2.2;
786:     origin.x += dir.x * 0.85;
787:     origin.z += dir.z * 0.85;
788: 
789:     for (let i = 0; i < el.shots; i++) {
790:       const offset = el.shots > 1 ? (i - (el.shots - 1) / 2) * el.spread : 0;
791:       const cs = Math.cos(offset);
792:       const sn = Math.sin(offset);
793:       const vx = dir.x * cs - dir.z * sn;
794:       const vz = dir.x * sn + dir.z * cs;
795:       const effect = {};
796:       if (f.id === 'fire') { effect.burnDps = 7; effect.burnTime = 3; }
797:       if (f.id === 'water') { effect.slow = 1.9; effect.heal = 4; }
798:       if (f.id === 'earth') { effect.knock = 4.2; }
799:       this.spawnProjectile({
800:         element: f.id,
801:         owner: f,
802:         from: origin,
803:         vel: new THREE.Vector3(vx * speed, 0, vz * speed),
804:         damage: el.damage,
805:         towerDamage: el.damage * el.towerMult,
806:         splash: el.splash,
807:         canHitTower: true,
808:         isTower: false,
809:         life: 32 / speed,
810:         effect
811:       });
812:     }
813:     f.castAnim = 0.32;
814:     this.fx.muzzle(origin.x, origin.y, origin.z, el.color);
815:     if (f.isPlayer) this.audio.cast(f.id);
816:   }
817: 
818:   spawnProjectile(cfg) {
819:     const mesh = this.fx.createProjectileMesh(cfg.element, { small: cfg.isTower });
820:     mesh.position.copy(cfg.from);
821:     this.projectileGroup.add(mesh);
822:     const p = {
823:       element: cfg.element,
824:       owner: cfg.owner,
825:       pos: cfg.from.clone(),
826:       prev: cfg.from.clone(),
827:       vel: cfg.vel.clone(),
828:       damage: cfg.damage,
829:       towerDamage: cfg.towerDamage,
830:       splash: cfg.splash,
831:       canHitTower: cfg.canHitTower,
832:       isTower: cfg.isTower,
833:       life: cfg.life,
834:       maxLife: cfg.life,
835:       mesh,
836:       effect: cfg.effect || {},
837:       trail: 0,
838:       dead: false
839:     };
840:     this.projectiles.push(p);
841:     return p;
842:   }
843: 
844:   removeProjectile(p) {
845:     if (p.dead) return;
846:     p.dead = true;
847:     this.projectileGroup.remove(p.mesh);
848:     p.mesh.traverse((child) => {
849:       if (child.geometry) child.geometry.dispose();
850:       if (child.material) {
851:         const mats = Array.isArray(child.material) ? child.material : [child.material];
852:         for (const m of mats) m.dispose();
853:       }
854:     });
855:     const idx = this.projectiles.indexOf(p);
856:     if (idx >= 0) this.projectiles.splice(idx, 1);
857:   }
858: 
859:   clearProjectiles() {
860:     for (const p of [...this.projectiles]) this.removeProjectile(p);
861:     this.projectiles.length = 0;
862:   }
863: 
864:   updateProjectiles(dt) {
865:     for (let i = this.projectiles.length - 1; i >= 0; i--) {
866:       const p = this.projectiles[i];
867:       p.life -= dt;
868:       p.prev.copy(p.pos);
869:       p.pos.addScaledVector(p.vel, dt);
870:       p.mesh.position.copy(p.pos);
871: 
872:       if (p.element === 'earth') {
873:         p.mesh.rotation.x += dt * 7;
874:         p.mesh.rotation.y += dt * 5;
875:       } else if (p.element === 'air') {
876:         p.mesh.rotation.y = Math.atan2(p.vel.x, p.vel.z);
877:       }
878:       if (p.mesh.userData.halo) p.mesh.userData.halo.rotation.z += dt * 9;
879: 
880:       p.trail -= dt;
881:       if (p.trail <= 0) {
882:         p.trail = 0.024;
883:         this.fx.trail(p.pos.x, p.pos.y, p.pos.z, ELEMENTS[p.element].color, p.isTower ? 0.32 : 0.44, 0.3);
884:       }
885: 
886:       let exploded = false;
887:       let directAvatar = null;
888:       let directTower = null;
889: 
890:       if (p.pos.y < 5.2) {
891:         for (const o of this.factions) {
892:           if (o === p.owner || !o.alive || !o.towerAlive) continue;
893:           const ap = o.avatar.root.position;
894:           const d2 = segDistSq2D(p.prev.x, p.prev.z, p.pos.x, p.pos.z, ap.x, ap.z);
895:           const r = AVATAR_RADIUS + (p.isTower ? 0.28 : 0.38);
896:           if (d2 < r * r && p.pos.y > 0.4) {
897:             directAvatar = o;
898:             exploded = true;
899:             this.hitAvatar(p, o);
900:             break;
901:           }
902:         }
903:       }
904: 
905:       if (!exploded && p.canHitTower && p.pos.y < 16.5) {
906:         for (const o of this.factions) {
907:           if (o === p.owner || !o.towerAlive) continue;
908:           const tp = o.tower.group.position;
909:           const d2 = segDistSq2D(p.prev.x, p.prev.z, p.pos.x, p.pos.z, tp.x, tp.z);
910:           if (d2 < (TOWER_RADIUS - 0.15) ** 2) {
911:             directTower = o;
912:             exploded = true;
913:             this.damageTower(o, p.towerDamage, p.owner, { projectile: p });
914:             break;
915:           }
916:         }
917:       }
918: 
919:       if (!exploded && (p.pos.y < 0.25)) {
920:         exploded = true;
921:       }
922: 
923:       if (exploded) {
924:         this.explodeProjectile(p, p.pos.x, Math.max(0.35, p.pos.y), p.pos.z, directAvatar, directTower);
925:       } else if (p.life <= 0) {
926:         this.removeProjectile(p);
927:       }
928:     }
929:   }
930: 
931:   hitAvatar(p, target) {
932:     const e = p.effect;
933:     this.damageAvatar(target, p.damage, p.owner, {
934:       slow: e.slow,
935:       burnDps: e.burnDps,
936:       burnTime: e.burnTime,
937:       knock: e.knock,
938:       knockFrom: p.owner ? p.owner.avatar.root.position : null
939:     });
940:     if (e.heal && p.owner && p.owner.alive) {
941:       this.heal(p.owner, e.heal);
942:       this.fx.trail(p.owner.avatar.root.position.x, 2.4, p.owner.avatar.root.position.z, ELEMENTS[p.owner.id].bright, 0.5, 0.35);
943:     }
944:   }
945: 
946:   explodeProjectile(p, x, y, z, directAvatar, directTower) {
947:     if (p.dead) return;
948:     const el = ELEMENTS[p.element];
949:     this.fx.impact(x, y, z, el.color, {
950:       count: p.isTower ? 8 : 16,
951:       speed: p.isTower ? 4 : 6,
952:       size: p.isTower ? 0.32 : 0.46,
953:       ring: p.splash > 1 ? p.splash + 1 : 2,
954:       ground: y < 0.9,
955:       flashSize: p.isTower ? 2.6 : 3.4
956:     });
957: 
958:     if (p.splash > 0.9 && !p.isTower) {
959:       const radius = p.splash + 1.05;
960:       for (const o of this.factions) {
961:         if (o === p.owner || !o.towerAlive) continue;
962:         if (o.alive && o !== directAvatar) {
963:           const ap = o.avatar.root.position;
964:           const d = Math.hypot(ap.x - x, ap.z - z);
965:           if (d < radius) {
966:             const falloff = Math.max(0.4, 1 - d / radius);
967:             this.damageAvatar(o, p.damage * falloff, p.owner, {
968:               slow: p.effect.slow,
969:               burnDps: p.effect.burnDps,
970:               burnTime: p.effect.burnTime,
971:               knock: p.effect.knock,
972:               knockFrom: p.owner ? p.owner.avatar.root.position : null
973:             });
974:           }
975:         }
976:         if (o.towerAlive && o !== directTower) {
977:           const tp = o.tower.group.position;
978:           const d = Math.hypot(tp.x - x, tp.z - z);
979:           if (d < radius + TOWER_RADIUS * 0.7) {
980:             const falloff = Math.max(0.3, 1 - d / (radius + TOWER_RADIUS));
981:             this.damageTower(o, p.towerDamage * 0.5 * falloff, p.owner, {});
982:           }
983:         }
984:       }
985:     }
986: 
987:     this.audio.impact(p.element, p.isTower ? 0.7 : 1);
988:     if (p.owner && p.owner.isPlayer) this.shake = Math.max(this.shake, p.splash > 2 ? 0.13 : 0.06);
989:     if (this.player && this.player.alive) {
990:       const pp = this.player.avatar.root.position;
991:       if (Math.hypot(pp.x - x, pp.z - z) < 4) this.shake = Math.max(this.shake, 0.16);
992:     }
993:     this.removeProjectile(p);
994:   }
995: 
996:   /* -------------------------------- damage -------------------------------- */
997: 
998:   damageAvatar(target, amount, source, opts = {}) {
999:     if (!target.alive || amount <= 0 || this.state === 'over') return 0;
