1344:   updateZones(dt) {
1345:     for (let i = this.zones.length - 1; i >= 0; i--) {
1346:       const z = this.zones[i];
1347:       z.life -= dt;
1348:       if (z.life <= 0) {
1349:         this.zones.splice(i, 1);
1350:         continue;
1351:       }
1352:       if (z.type !== 'cyclone') continue;
1353:       const owner = z.owner;
1354: 
1355:       /* drift toward the nearest living victim */
1356:       let victim = null;
1357:       let vd = 30;
1358:       for (const o of this.factions) {
1359:         if (o === owner || !o.alive || !o.towerAlive) continue;
1360:         const p = o.avatar.root.position;
1361:         const d = Math.hypot(p.x - z.center.x, p.z - z.center.z);
1362:         if (d < vd) { vd = d; victim = p; }
1363:       }
1364:       if (victim) {
1365:         const dx = victim.x - z.center.x;
1366:         const dz = victim.z - z.center.z;
1367:         const d = Math.hypot(dx, dz) || 1;
1368:         z.center.x += (dx / d) * 2.0 * dt;
1369:         z.center.z += (dz / d) * 2.0 * dt;
1370:       }
1371:       const rad = Math.hypot(z.center.x, z.center.z);
1372:       if (rad > PLAY_RADIUS - 3) {
1373:         z.center.x = (z.center.x / rad) * (PLAY_RADIUS - 3);
1374:         z.center.z = (z.center.z / rad) * (PLAY_RADIUS - 3);
1375:       }
1376:       z.visual.group.position.set(z.center.x, 0, z.center.z);
1377: 
1378:       /* pull + damage */
1379:       for (const o of this.factions) {
1380:         if (o === owner || !o.alive || !o.towerAlive) continue;
1381:         const p = o.avatar.root.position;
1382:         const dx = z.center.x - p.x;
1383:         const dz = z.center.z - p.z;
1384:         const d = Math.hypot(dx, dz);
1385:         if (d < 9 && d > 0.5) {
