  background: var(--pick); border: 2px solid #0a0c16;
}
.player-meta { flex: 1; min-width: 0; }
.player-name-row { display: flex; align-items: baseline; gap: 7px; line-height: 1; margin-bottom: 7px; }
.player-name-row span { font-family: 'Cinzel', serif; font-size: 15px; font-weight: 800; letter-spacing: 0.11em; color: #f6f8ff; }
.player-name-row em { font-style: normal; font-size: 8px; font-weight: 700; letter-spacing: 0.18em; color: var(--pick); white-space: nowrap; }
.hp-bar { height: 7px; background: rgba(255, 255, 255, 0.09); }
.hp-bar > i { background: linear-gradient(90deg, #7ecfa3, #b9f3cd); box-shadow: 0 0 12px rgba(120, 230, 170, 0.3); }
.hp-bar.low > i { background: linear-gradient(90deg, #ff5a4a, #ffb07e); box-shadow: 0 0 12px rgba(255, 90, 70, 0.5); }
.hp-bar > b {
  position: absolute; inset: 0;
  background-image: repeating-linear-gradient(90deg, transparent 0 18%, rgba(4, 7, 14, 0.55) 18% 18.8%);
  pointer-events: none;
}
.player-numbers { display: flex; justify-content: space-between; gap: 6px; margin-top: 3px; font-size: 9px; font-weight: 600; letter-spacing: 0.08em; color: #8e9ab8; }
.player-numbers #playerState { color: #b8c4df; }
.player-numbers #playerState.danger { color: #ff917d; }
.ult-row { display: flex; align-items: center; gap: 6px; margin-top: 5px; }
.ult-tag { font-size: 7px; font-weight: 700; letter-spacing: 0.16em; color: var(--pick); }
.ult-bar { flex: 1; height: 3px; background: rgba(255, 255, 255, 0.08); }
.ult-bar > i { background: linear-gradient(90deg, var(--pick), var(--pick-bright, #fff)); box-shadow: 0 0 10px var(--pick); }
.ult-row > span:last-child { font-size: 8.5px; font-weight: 700; color: #94a0bd; min-width: 26px; text-align: right; }
.ult-row.ready > span:last-child { color: var(--pick-bright); text-shadow: 0 0 10px var(--pick); }

#abilities {
  position: absolute;
  left: 50%;
  bottom: calc(20px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  gap: 9px;
  align-items: flex-end;
}
.ability {
  --c: var(--pick);
  --cd: 0;
  position: relative;
  width: 68px;
  height: 68px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.06), transparent 45%),
    linear-gradient(180deg, rgba(10, 14, 28, 0.87), rgba(5, 8, 18, 0.8));
  border: 1px solid var(--line);
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
  backdrop-filter: blur(12px);
  box-shadow: 0 10px 30px -18px #000;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.ability::before {
  content: '';
  position: absolute;
  inset: 0;
  background: conic-gradient(rgba(3, 5, 12, 0.83) calc(var(--cd) * 1turn), transparent 0);
  pointer-events: none;
  z-index: 1;
}
.ability .ab-icon { color: var(--c); display: grid; place-items: center; filter: drop-shadow(0 0 7px color-mix(in srgb, var(--c) 55%, transparent)); }
.ability .ab-icon .icon { width: 25px; height: 25px; }
.ability .ab-key {
  position: absolute; top: 3px; left: 5px;
  font-size: 7.5px; font-weight: 700; letter-spacing: 0.1em; color: #8f9ab7;
  text-align: center;
  pointer-events: none;
  padding: 16px 40px 18px;
  background: radial-gradient(60% 100% at 50% 50%, rgba(4, 7, 15, 0.86), transparent 100%);
}
#respawnOverlay span { font-size: 10px; font-weight: 700; letter-spacing: 0.36em; color: #ff9c84; text-transform: uppercase; }
#respawnOverlay strong { font-family: 'Cinzel', serif; font-size: 46px; font-weight: 800; color: #fff2ec; line-height: 1; text-shadow: 0 0 30px rgba(255, 90, 60, 0.4); }
#respawnOverlay em { font-style: normal; font-size: 10px; letter-spacing: 0.2em; color: #a6b0ca; text-transform: uppercase; }

#crosshair {
  position: absolute;
  left: 50%;
  top: 52%;
  width: 34px;
  height: 34px;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 14;
  filter: drop-shadow(0 0 6px var(--pick));
  transition: opacity 0.2s;
}
.ch-ring { position: absolute; inset: 7px; border: 1px solid color-mix(in srgb, var(--pick) 80%, white); border-radius: 50%; opacity: 0.75; }
.ch-ring::before { content: ''; position: absolute; inset: -6px; border: 1px dashed color-mix(in srgb, var(--pick) 40%, transparent); border-radius: 50%; animation: spin 10s linear infinite; }
.ch-dot { position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; background: #fff; border-radius: 50%; transform: translate(-50%, -50%); box-shadow: 0 0 8px var(--pick); }
.ch-tick { position: absolute; width: 1px; height: 6px; background: color-mix(in srgb, var(--pick) 80%, white); }
.ch-tick.t1 { left: 50%; top: -1px; }
.ch-tick.t2 { left: 50%; bottom: -1px; }
.ch-tick.t3 { top: 50%; left: -1px; height: 1px; width: 6px; }
.ch-tick.t4 { top: 50%; right: -1px; height: 1px; width: 6px; }

#pauseBtn {
  position: absolute;
  top: calc(13px + var(--safe-top));
  right: calc(18px + var(--safe-right));
  width: 38px; height: 38px;
  pointer-events: auto;
  background: rgba(8, 12, 25, 0.55);
}
#powerHint {
  position: absolute;
  left: 50%;
  bottom: 110px;
  transform: translateX(-50%);
  font-size: 9px;
  letter-spacing: 0.2em;
  color: #d6c39a;
  text-transform: uppercase;
  font-weight: 600;
  text-shadow: 0 0 20px rgba(0,0,0,.8);
}

/* ================================ TOUCH ================================= */
#touchControls { position: absolute; inset: 0; z-index: 13; pointer-events: none; }
#touchControls .stick {
  position: absolute;
  width: 132px; height: 132px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(10, 15, 30, 0.18) 40%, rgba(10, 15, 30, 0.42));
  border: 1px solid rgba(255, 255, 255, 0.14);
  pointer-events: auto;
  touch-action: none;
  backdrop-filter: blur(3px);
}
#touchControls .stick.aim { border-color: color-mix(in srgb, var(--pick) 45%, transparent); }
#moveStick { left: calc(18px + var(--safe-left)); bottom: calc(18px + var(--safe-bottom)); }
#aimStick { right: calc(18px + var(--safe-right)); bottom: calc(18px + var(--safe-bottom)); }
.stick-ring { position: absolute; inset: 22px; border: 1px dashed rgba(255, 255, 255, 0.16); border-radius: 50%; }
.stick-knob {
  position: absolute; left: 50%; top: 50%;
  width: 56px; height: 56px; border-radius: 50%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.28), rgba(18, 24, 42, 0.85));
  border: 1px solid rgba(255, 255, 255, 0.3);
  box-shadow: 0 6px 20px -6px #000;
}
#aimStick .stick-knob { border-color: color-mix(in srgb, var(--pick) 60%, transparent); box-shadow: 0 0 18px -6px var(--pick); }
.stick-label {
  position: absolute; bottom: 8px; left: 0; right: 0;
  text-align: center; font-size: 7px; font-weight: 700; letter-spacing: 0.2em; color: #96a1bc;
}
.touch-btn {
  position: absolute;
  width: 60px; height: 60px;
  border-radius: 50%;
  display: grid; place-items: center;
  background: rgba(9, 13, 27, 0.7);
  border: 1px solid var(--line);
  color: #dbe3f7;
  pointer-events: auto;
  touch-action: none;
  backdrop-filter: blur(8px);
  transition: transform 0.1s, opacity 0.2s;
}
.touch-btn .icon { width: 25px; height: 25px; }
.touch-btn:active { transform: scale(0.9); }
.touch-btn i { position: absolute; inset: -2px; border-radius: 50%; background: conic-gradient(rgba(3, 5, 12, 0.72) calc(var(--cd, 0) * 1turn), transparent 0); }
.touch-btn.ult { --c: var(--pick); border-color: color-mix(in srgb, var(--c) 55%, transparent); color: var(--c); }
.touch-btn.ult.ready { box-shadow: 0 0 26px -4px var(--c); }
#touchDash { right: calc(166px + var(--safe-right)); bottom: calc(34px + var(--safe-bottom)); }
#touchUlt { right: calc(38px + var(--safe-right)); bottom: calc(166px + var(--safe-bottom)); }

/* ================================ MODALS ================================ */
.modal {
  position: absolute; inset: 0; z-index: 40;
  display: grid; place-items: center;
  padding: 20px;
  background: rgba(2, 4, 10, 0.7);
  backdrop-filter: blur(10px);
}
.modal-panel {
  position: relative;
  width: min(860px, 100%);
  max-height: min(86vh, 760px);
  overflow-y: auto;
  padding: 30px 38px 26px;
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.05), transparent 32%),
