  border: 1px solid var(--line);
  border-top-color: rgba(232, 200, 138, 0.4);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
  .subtitle { font-size: 10px; letter-spacing: 0.2em; }
  .menu-foot { font-size: 8.5px; letter-spacing: 0.14em; }
  .control-hint { font-size: 9px; gap: 7px; }
  .menu-actions { width: 100%; }
  .btn-primary { flex: 1; min-width: 0; padding: 14px 20px 13px; }
  .btn-ghost { padding: 13px 18px 12px; }
  #minimapPanel { display: none; }
  #feed { display: none; }
  #playerPanel { width: 224px; padding: 9px 11px 9px 9px; }
  .portrait-wrap { width: 46px; height: 46px; }
  .portrait { width: 37px; height: 37px; }
  .portrait .icon { width: 22px; height: 22px; }
  .player-name-row span { font-size: 13px; }
  .match-objective { display: none; }
  .match-meta { gap: 10px; }
  #abilities { bottom: calc(14px + var(--safe-bottom)); gap: 7px; }
  .ability { width: 58px; height: 58px; }
  .ability.main { width: 66px; height: 66px; }
  .ability .ab-name { display: none; }
  .ability .ab-icon .icon { width: 22px; height: 22px; }
  .ability.main .ab-icon .icon { width: 27px; height: 27px; }
  #crosshair { display: none; }
  .how-grid { grid-template-columns: 1fr; gap: 16px; }
  .tip-grid { grid-template-columns: repeat(2, 1fr); }
  .modal-panel { padding: 26px 20px 20px; }
}

@media (max-width: 560px) {
  .menu-screen { padding-top: calc(12px + var(--safe-top)); justify-content: flex-start; gap: 10px; }
  .brand-word { display: none; }
  .icon-text-btn span { display: none; }
