import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
import { readFileSync, mkdirSync } from 'node:fs';
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const fails = [];
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE', m.type(), m.text()); });
page.on('pageerror', (e) => { console.log('PAGEERROR', e.message, e.stack); fails.push(e.message); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1200);
await page.locator('#startBtn').click();
await page.waitForTimeout(1200);
mkdirSync('/tmp/opencode/shots', { recursive: true });
console.log('state0', await page.evaluate(() => window.__nexus.game.state));

// Move inward toward the centre for a more representative view.
await page.keyboard.down('s');
await page.waitForTimeout(1400);
await page.keyboard.up('s');
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/shots/game-center.png' });
console.log('player', await page.evaluate(() => {
  const p = window.__nexus.game.player.avatar.root.position;
  return { x: p.x, z: p.z, hp: window.__nexus.game.player.hp };
}));

// Aim at water avatar, hold fire for a moment.
const waterScreen = await page.evaluate(() => {
  const g = window.__nexus.game;
  const f = g.byId.water;
  const v = f.avatar.root.position.clone();
  v.y = 2.2;
  v.project(g.camera);
  return { x: (v.x * 0.5 + 0.5) * innerWidth, y: (-v.y * 0.5 + 0.5) * innerHeight };
});
console.log('waterScreen', waterScreen);
await page.mouse.move(waterScreen.x, waterScreen.y);
await page.mouse.down();
await page.waitForTimeout(1500);
await page.mouse.up();
await page.waitForTimeout(300);
console.log('water hp after fire', await page.evaluate(() => window.__nexus.game.byId.water.hp));
await page.screenshot({ path: '/tmp/opencode/shots/game-fire.png' });

// Charge and cast ultimate at the water tower.
await page.evaluate(() => {
  const g = window.__nexus.game;
  g.player.ult = 100;
  const p = g.byId.water.tower.group.position;
  g.player.avatar.root.position.set(p.x - 8, 0, p.z);
  g.aimPoint.set(p.x, 0, p.z);
  g.aimDir.set(1, 0, 0);
});
await page.keyboard.press('e');
await page.waitForTimeout(700);
await page.screenshot({ path: '/tmp/opencode/shots/game-ult.png' });
await page.waitForTimeout(2500);
console.log('water tower after ult', await page.evaluate(() => window.__nexus.game.byId.water.towerHp));

// Pause and resume.
await page.keyboard.press('Escape');
await page.waitForTimeout(300);
console.log('paused', await page.evaluate(() => ({ state: window.__nexus.game.state, visible: !document.getElementById('pauseScreen').classList.contains('hidden') })));
await page.screenshot({ path: '/tmp/opencode/shots/pause.png' });
await page.keyboard.press('Escape');
await page.waitForTimeout(200);
console.log('resumed', await page.evaluate(() => window.__nexus.game.state));

// Force victory by destroying all rival towers.
await page.evaluate(() => {
  const g = window.__nexus.game;
  for (const f of g.factions) {
    if (f !== g.player && f.towerAlive) g.damageTower(f, 9999, g.player, {});
  }
});
await page.waitForTimeout(2000);
console.log('ending', await page.evaluate(() => ({ state: window.__nexus.game.state, result: window.__nexus.game.endResult })));
await page.waitForTimeout(1200);
console.log('end screen', await page.evaluate(() => ({ state: window.__nexus.game.state, hidden: document.getElementById('endScreen').classList.contains('hidden'), title: document.getElementById('endTitle').textContent })));
await page.screenshot({ path: '/tmp/opencode/shots/victory.png' });
console.log('fails', fails);
await browser.close();

