import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium, devices } = require('playwright');
import { readFileSync, mkdirSync } from 'node:fs';
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const ctx = await browser.newContext({ ...devices['iPhone 13'] });
const page = await ctx.newPage();
const fails = [];
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE', m.type(), m.text()); });
page.on('pageerror', (e) => { console.log('PAGEERROR', e.message, e.stack); fails.push(e.message); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(1200);
mkdirSync('/tmp/opencode/shots', { recursive: true });
await page.screenshot({ path: '/tmp/opencode/shots/mobile-menu.png' });
console.log('touch class', await page.evaluate(() => document.body.classList.contains('touch')));
console.log('start box', await page.locator('#startBtn').boundingBox());
await page.locator('#startBtn').tap();
await page.waitForTimeout(1400);
console.log('state', await page.evaluate(() => window.__nexus.game.state));
console.log('touch controls', await page.evaluate(() => !document.getElementById('touchControls').classList.contains('hidden')));
console.log('abilities display', await page.evaluate(() => getComputedStyle(document.getElementById('abilities')).display));
await page.screenshot({ path: '/tmp/opencode/shots/mobile-game.png' });

// Touch drag the left stick upward via CDP.
const move = await page.locator('#moveStick').boundingBox();
const cdp = await ctx.newCDPSession(page);
const mx = move.x + move.width / 2;
const my = move.y + move.height / 2;
const before = await page.evaluate(() => {
  const p = window.__nexus.game.player.avatar.root.position;
  return { x: p.x, z: p.z };
});
await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: mx, y: my, id: 1 }] });
await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: mx, y: my - 45, id: 1 }] });
await page.waitForTimeout(1300);
await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
await page.waitForTimeout(200);
const after = await page.evaluate(() => {
  const g = window.__nexus.game;
  const p = g.player.avatar.root.position;
  return { x: p.x, z: p.z, input: { ...g.input, aimNDC: undefined, touchAim: { ...g.input.touchAim } } };
});
console.log('move before', before, 'after', { x: after.x, z: after.z }, 'input', after.input);

// Aim stick up-right and verify cast.
const aim = await page.locator('#aimStick').boundingBox();
const ax = aim.x + aim.width / 2;
const ay = aim.y + aim.height / 2;
const projBefore = await page.evaluate(() => window.__nexus.game.projectiles.length);
await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: ax, y: ay, id: 2 }] });
await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: ax + 34, y: ay - 30, id: 2 }] });
await page.waitForTimeout(1300);
const projAfter = await page.evaluate(() => window.__nexus.game.projectiles.length);
await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
console.log('projectiles', projBefore, '->', projAfter);
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/opencode/shots/mobile-action.png' });

// Touch ultimate button should show the not-charged hint without crashing.
await page.locator('#touchUlt').tap();
await page.waitForTimeout(200);
console.log('ult hint', await page.evaluate(() => document.getElementById('powerHint').textContent));
console.log('fails', fails);
await browser.close();

