  const { game, fx, input } = window.__nexus;
  input.moveX = 0; input.moveZ = 0; input.firing = false; input.pointerActive = false;
  const log = [];
  const dt = 1 / 60;
  let t = 0;
  for (let i = 0; i < 60 * 60; i++) {
    t += dt;
    game.update(dt, t, input);
    fx.update(dt, t);
    if (i % (60 * 5) === 0) {
      log.push({
        t: Math.round(t),
        state: game.state,
        player: { hp: Math.round(game.player.hp), alive: game.player.alive, tower: Math.round(game.player.towerHp) },
        towers: game.factions.map((f) => `${f.id}:${Math.round(f.towerHp)}${f.towerAlive ? '' : 'X'}`).join(' '),
        avatars: game.factions.map((f) => `${f.id}:${Math.round(f.hp)}${f.alive ? '' : 'X'}`).join(' ')
      });
    }
    if (game.state === 'over') break;
  }
  return log;
});
console.table(result);
await browser.close();

