process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const fails = [];
page.on('pageerror', (e) => { console.log('PAGEERROR', e.message, e.stack); fails.push(e.message); });
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForTimeout(700);
for (const id of ['fire', 'water', 'earth', 'air']) {
  const out = await page.evaluate((element) => {
    const { game, fx, input } = window.__nexus;
    input.moveX = 0; input.moveZ = 0; input.firing = false;
    game.startBattle(element);
    game.player.ult = 100;
    game.aimPoint.set(8, 0, 0);
    game.tryUlt();
    let t = game.elapsed;
    const dt = 1 / 60;
    for (let i = 0; i < 60 * 5; i++) {
      t += dt;
      game.update(dt, t, input);
      fx.update(dt, t);
    }
    return {
      id: element,
      state: game.state,
      ult: Math.round(game.player.ult),
      fx: { rings: fx.rings.length, meteors: fx.meteors.length, cyclones: fx.cyclones.length, telegraphs: fx.telegraphs.length, debris: fx.debrisBursts.length, texts: fx.texts.length },
      hp: Math.round(game.player.hp),
      tower: Math.round(game.player.towerHp),
      zones: game.zones.length
    };
  }, id);
  console.log(out);
  await page.waitForTimeout(250);
}
// Defeat path.
const defeat = await page.evaluate(() => {
  const { game, fx, input } = window.__nexus;
  game.startBattle('water');
  const enemy = game.byId.earth;
  game.damageTower(game.player, 9999, enemy, {});
  for (let i = 0; i < 60 * 3; i++) {
    game.update(1 / 60, i / 60, input);
    fx.update(1 / 60, i / 60);
  }
  return { state: game.state, result: game.endResult, winner: game.endWinner?.id, title: document.getElementById('endTitle').textContent };
});
