  .tip-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-height: 680px) and (min-width: 800px) {
  .menu-main { padding-top: 0; }
  .title-block { margin-bottom: 10px; }
  .game-title em { font-size: clamp(44px, 7vw, 76px); }
  .card-desc { display: none; }
  .element-card { padding: 11px 12px 9px; }
  .card-glyph { height: 38px; width: 38px; }
  .card-glyph .icon { width: 32px; height: 32px; }
  .card-stats { margin-top: 6px; }
  .control-hint { margin-top: 10px; }
}

@media (max-height: 480px) and (orientation: landscape) {
  #playerPanel { transform: scale(0.82); transform-origin: bottom left; }
  #abilities { transform: translateX(-50%) scale(0.8); transform-origin: bottom center; }
  #minimapPanel { display: none; }
  .menu-screen { padding-top: 8px; }
  .title-block { margin-bottom: 4px; }
  .game-title em { font-size: 38px; }
  .game-title span { font-size: 10px; }
  .subtitle { display: none; }
  .element-grid { grid-template-columns: repeat(4, 1fr); }
  .element-card { padding: 8px; }
  .card-glyph, .card-desc, .card-stats, .card-ult, .card-role { display: none; }
  .card-name { font-size: 14px; }
  .menu-actions { margin-top: 6px; }
  .control-hint { display: none; }
  .end-panel, .pause-panel { padding: 14px 24px 12px; max-height: calc(100vh - 24px); }
  .end-panel h2, .pause-panel h2 { font-size: 30px; margin: 0 0 4px; }
  .end-kicker { font-size: 7px; letter-spacing: 0.3em; }
  #endSubtitle { font-size: 8px; }
  .end-emblem { width: 40px; height: 40px; margin: 4px auto 0; }
  .end-emblem .icon { width: 24px; height: 24px; }
  .end-stats { margin-top: 8px; }
  .end-stat { padding: 5px 6px 4px; }
  .end-stat strong { font-size: 16px; }
  .end-stat span { font-size: 6px; margin-top: 0; letter-spacing: 0.12em; }
  .end-actions { margin-top: 8px; gap: 8px; }
  .end-actions .btn-primary, .end-actions .btn-ghost { flex: 0 1 auto; padding: 8px 18px 7px; font-size: 9px; letter-spacing: 0.12em; }
  .pause-actions { margin-top: 8px; gap: 8px; }
  .pause-note { margin-top: 6px; font-size: 8px; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  #grain, .portrait-ring::before, .portrait-ring::after, .ch-ring::before, .btn-primary .btn-glint { animation: none; }
  .element-card, .btn-primary, .ability, .icon-btn { transition-duration: 0.01ms; }
}

