import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
import { readFileSync } from 'node:fs';
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
const fails=[]; page.on('pageerror', e=>{console.log('PAGEERROR',e.message);fails.push(e.message)});
await page.goto('http://localhost:3002/', {waitUntil:'load'});
await page.waitForTimeout(600);
const out = await page.evaluate(() => {
  const {game,fx,input}=window.__nexus;
  game.startBattle('fire');
  for (const f of game.factions) { f.towerCd = 999; f.ai.think = 999; if(!f.isPlayer) f.stunTime = 999; }
  game.player.avatar.root.position.set(0,0,0);
  game.byId.water.avatar.root.position.set(12,0,0);
  game.byId.water.avatar.root.rotation.y = 0;
  game.aimPoint.set(12,1.4,0); game.aimDir.set(1,0,0);
  input.touchAim = {x:1,y:0,active:true};
  input.firing = true;
  let t=0; const dt=1/60;
  const startHp = game.byId.water.hp;
  for(let i=0;i<180;i++){t+=dt;game.update(dt,t,input);fx.update(dt,t);}
  const midHp = game.byId.water.hp;
  // Kill it outright and verify respawn.
  game.damageAvatar(game.byId.water, 9999, game.player, {});
  const dead = {alive: game.byId.water.alive, visible: game.byId.water.avatar.root.visible};
  for(let i=0;i<60*7;i++){t+=dt;game.update(dt,t,input);fx.update(dt,t);}
  return {startHp, midHp, dead, respawned: game.byId.water.alive, respawnHp: Math.round(game.byId.water.hp), playerKills: game.player.kills, stats: game.stats, state: game.state};
});
console.log(out); console.log('fails',fails);
await browser.close();

