      const { pebbles, gem } = rig.extra;
      for (const p of pebbles) {
        p.a += dt * p.speed;
        p.mesh.position.set(Math.cos(p.a) * p.r, p.y + Math.sin(t * 1.1 + p.a) * 0.22 - rig.body.position.y, Math.sin(p.a) * p.r);
        p.mesh.rotation.x += dt * 0.7;
        p.mesh.rotation.y += dt * 0.5;
