  function easeOutBack(x) {
    const c = 1.70158;
    const c3 = c + 1;
    return 1 + c3 * Math.pow(x - 1, 3) + c * Math.pow(x - 1, 2);
  }

  function setVisible(v) { rig.root.visible = v; }

  return {
    id,
