    n.game.state = 'paused';
    const avatar = n.game.byId[avatarId].avatar;
    avatar.reset();
    avatar.root.visible = true;
    avatar.root.position.set(0, 0, 0);
    avatar.root.rotation.set(0, 0, 0);
    avatar.healthSprite.visible = false;
    avatar.rig.shadow.visible = false;
    avatar.rig.groundRing.visible = false;
    avatar.rig.groundRing2.visible = false;
    avatar.rig.aura.material.opacity = 0.28;
    avatar.update(0.016, 1.2, { moving: false, casting: false });

    const scene = new THREE.Scene();
    scene.add(avatar.root);
    scene.add(new THREE.HemisphereLight(0x9fb4ff, 0x24140c, 1.7));
    const key = new THREE.DirectionalLight(0xfff0d8, 3.1);
    key.position.set(-4, 7, 6);
    scene.add(key);
    const rim = new THREE.DirectionalLight(0x8d7dff, 2.2);
    rim.position.set(4, 4, -4);
    scene.add(rim);
    const fill = new THREE.DirectionalLight(0xffb27a, 0.9);
    fill.position.set(4, 2, 5);
    scene.add(fill);

    const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 50);
    camera.position.set(0.25, 3.5, 4.5);
    camera.lookAt(0, 3.15, 0);
    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true, preserveDrawingBuffer: true });
    renderer.setSize(512, 512, false);
    renderer.setPixelRatio(2);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
